import type { QueryInterface } from 'sequelize';

// Adds media.serial_code: "RC-{yyyymmdd}-{######}", generated by the DB on insert. The date is the save date and
// ###### comes from media_serial_code_seq, so it never repeats (the sequence errors instead of cycling at 999999).
// Existing rows are numbered by created_at and the sequence continues after them.
export async function up(queryInterface: QueryInterface) {
  await queryInterface.sequelize.transaction(async (transaction) => {
    const run = (sql: string) => queryInterface.sequelize.query(sql, { transaction });

    await run('CREATE SEQUENCE IF NOT EXISTS media_serial_code_seq MINVALUE 1 MAXVALUE 999999 NO CYCLE');
    await run('ALTER TABLE media ADD COLUMN IF NOT EXISTS serial_code VARCHAR(20)');
    await run(`
      WITH numbered AS (SELECT id, row_number() OVER (ORDER BY created_at, id) AS n FROM media)
      UPDATE media m
         SET serial_code = 'RC-' || to_char(m.created_at AT TIME ZONE 'America/Lima', 'YYYYMMDD') || '-' || lpad(numbered.n::text, 6, '0')
        FROM numbered
       WHERE m.id = numbered.id AND m.serial_code IS NULL`);
    await run(`SELECT setval('media_serial_code_seq', GREATEST((SELECT COUNT(*) FROM media), 1), (SELECT COUNT(*) FROM media) > 0)`);
    await run(`
      ALTER TABLE media ALTER COLUMN serial_code
        SET DEFAULT 'RC-' || to_char(now() AT TIME ZONE 'America/Lima', 'YYYYMMDD') || '-' || lpad(nextval('media_serial_code_seq')::text, 6, '0')`);
    await run('ALTER TABLE media ALTER COLUMN serial_code SET NOT NULL');
    await run('ALTER SEQUENCE media_serial_code_seq OWNED BY media.serial_code');
    await run('CREATE UNIQUE INDEX IF NOT EXISTS media_serial_code_key ON media (serial_code)');
  });
}

export async function down(queryInterface: QueryInterface) {
  // Dropping the column also drops the sequence (OWNED BY) and the unique index.
  await queryInterface.sequelize.query('ALTER TABLE media DROP COLUMN IF EXISTS serial_code');
}
